import { chainClient, checkAbort, contractInterface, ChainDataError } from './client.js';
import { sharedEventRead } from './event-store.js';

// DegenerusDeityPass.mint rejects IDs >= 32. ownerOf returns _owners[id],
// whose only in-range revert is InvalidToken for an unminted symbol. Issued
// owners are retained under the product's permanent-ownership assumption;
// only missing symbols need refreshes to discover new purchases.
const SYMBOL_COUNT = 32;
const OWNER_BATCH = 16;

function unminted(error, address, data, invalidToken) {
  // The snapshot's Multicall adapter identifies a failed individual getter.
  // Its exact target/calldata plus the verified name and bounded token ID
  // distinguish this contract's absent token from transport/decoding failures.
  if (error?.code === 'CALL_REVERTED' && error.address === address && error.data === data) return true;
  // A provider without Multicall returns the contract's revert bytes directly.
  return [error?.data, error?.error?.data, error?.info?.error?.data]
    .some(value => typeof value === 'string' && value.toLowerCase() === invalidToken);
}

function catalogCopy(ownersBySymbol) {
  return { issuedCount: ownersBySymbol.size, takenSymbols: new Set(ownersBySymbol.keys()), ownersBySymbol: new Map(ownersBySymbol) };
}

export async function readDeityCatalog({ client = chainClient(), signal, knownOwners } = {}) {
  checkAbort(signal);
  const address = client.address('DEITY_PASS');
  const scope = `${client.chain.id}:${address}:${client.chain.deployBlock}`;
  const retained = client.deityCatalogOwners?.scope === scope ? client.deityCatalogOwners.ownersBySymbol : null;
  // The presentation cache is already deployment-scoped and contains only
  // previously verified catalog results. Never retain zero/malformed owners.
  const known = new Map(retained);
  if (knownOwners instanceof Map) for (const [symbol, value] of knownOwners) {
    const owner = String(value).toLowerCase();
    if (Number.isInteger(symbol) && symbol >= 0 && symbol < SYMBOL_COUNT
      && /^0x[0-9a-f]{40}$/.test(owner) && !/^0x0{40}$/.test(owner) && !known.has(symbol)) known.set(symbol, owner);
  }
  if (known.size === SYMBOL_COUNT) return catalogCopy(known);
  const snapshot = await client.snapshot({ signal });
  checkAbort(signal);
  snapshot.deityCatalogFlights ??= new Map();
  const catalog = snapshot.deityCatalog ?? await sharedEventRead(snapshot.deityCatalogFlights, 'owners', async sharedSignal => {
    const iface = await contractInterface('DEITY_PASS');
    checkAbort(sharedSignal);
    const invalidToken = iface.getError('InvalidToken').selector.toLowerCase();
    const ownersBySymbol = new Map(known);
    const missing = Array.from({ length: SYMBOL_COUNT }, (_, symbol) => symbol).filter(symbol => !known.has(symbol));
    for (let start = 0; start < missing.length; start += OWNER_BATCH) {
      checkAbort(sharedSignal);
      // Keep the name proof in the first aggregate; a stale/empty deployment
      // must never turn 32 failed owner calls into 32 purchasable symbols.
      const name = start === 0 ? snapshot.call('DEITY_PASS', 'name') : null;
      const symbols = missing.slice(start, start + OWNER_BATCH);
      const reads = symbols.map(symbol => snapshot.call('DEITY_PASS', 'ownerOf', [symbol]));
      const [proof, ...owners] = await Promise.allSettled([name, ...reads]);
      checkAbort(sharedSignal);
      if (start === 0 && (proof.status !== 'fulfilled' || proof.value !== 'Degenerus Deity Pass')) {
        throw proof.status === 'rejected' ? proof.reason : new ChainDataError('Invalid deity pass deployment.');
      }
      for (let offset = 0; offset < owners.length; offset++) {
        const symbol = symbols[offset], result = owners[offset];
        if (result.status === 'rejected') {
          if (unminted(result.reason, address, iface.encodeFunctionData('ownerOf', [symbol]), invalidToken)) continue;
          throw result.reason;
        }
        const owner = String(result.value).toLowerCase();
        if (!/^0x[0-9a-f]{40}$/.test(owner) || /^0x0{40}$/.test(owner)) {
          throw new ChainDataError('Invalid deity owner.');
        }
        ownersBySymbol.set(symbol, owner);
      }
    }
    await snapshot.verify(sharedSignal);
    checkAbort(sharedSignal);
    const result = { issuedCount: ownersBySymbol.size, takenSymbols: new Set(ownersBySymbol.keys()), ownersBySymbol };
    client.deityCatalogOwners = { scope, ownersBySymbol: new Map(ownersBySymbol) };
    snapshot.deityCatalog = result;
    return result;
  }, signal);
  checkAbort(signal);
  return catalogCopy(catalog.ownersBySymbol);
}
